Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "filter": "isValid(datum[''Não realizada (GWh)''])"
    },
    {
      "calculate": "time(datum[''Data''])",
      "as": "t"
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "t",
          "as": "tmax"
        }
      ]
    },
    {
      "filter": "datum.t > datum.tmax - 364 * 86400000"
    },
    {
      "joinaggregate": [
        {
          "op": "min",
          "field": "t",
          "as": "tmin"
        }
      ]
    },
    {
      "calculate": "floor((datum.t - datum.tmin + day(datum.tmin) * 86400000) / (7 * 86400000))",
      "as": "semana"
    },
    {
      "calculate": "day(datum[''Data''])",
      "as": "dia_sem"
    },
    {
      "calculate": "[''jan'',''fev'',''mar'',''abr'',''mai'',''jun'',''jul'',''ago'',''set'',''out'',''nov'',''dez''][month(datum[''Data''])]",
      "as": "mes"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rect",
        "stroke": "#FFFFFF",
        "strokeWidth": 1.5
      },
      "encoding": {
        "x": {
          "field": "semana",
          "type": "ordinal",
          "axis": null
        },
        "y": {
          "field": "dia_sem",
          "type": "ordinal",
          "title": null,
          "axis": {
            "labelExpr": "[''dom'',''seg'',''ter'',''qua'',''qui'',''sex'',''sáb''][datum.value]",
            "ticks": false,
            "labelFontSize": 9
          }
        },
        "color": {
          "field": "Não realizada (GWh)",
          "type": "quantitative",
          "scale": {
            "type": "sqrt",
            "range": [
              "#F6F5F3",
              "#F2C811",
              "#967100",
              "#191919"
            ]
          },
          "legend": {
            "orient": "bottom",
            "title": "GWh no dia",
            "gradientLength": 160,
            "format": ",.1f"
          }
        },
        "tooltip": [
          {
            "field": "Data",
            "type": "temporal",
            "title": "Dia",
            "format": "%d/%m/%Y"
          },
          {
            "field": "Não realizada (GWh)",
            "title": "Não realizada (GWh)",
            "format": ",.1f"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "filter": "date(datum[''Data'']) <= 7 && day(datum[''Data'']) == 0"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "bottom",
        "fontSize": 9,
        "color": "#605E5C",
        "dy": -2
      },
      "encoding": {
        "x": {
          "field": "semana",
          "type": "ordinal"
        },
        "y": {
          "value": 0
        },
        "text": {
          "field": "mes"
        }
      }
    }
  ]
}'
